DevTools = {
  controllers: new WeakMap(),
  init: function(app, container) {
    container = container || $(".component[name=DevTools]");
    const root = container.find('.devtools-api').get(0);
    if (!root || root.dataset.ready === 'true') return;
    root.dataset.ready = 'true';
    const $root = $(root);
    const addHeader = function(name, value) {
      const row = $('<div class="dt-header-row"></div>');
      row.append($('<input type="text" class="dt-header-name" aria-label="Header name" placeholder="Header name">').val(name || ''));
      row.append($('<input type="text" class="dt-header-value" aria-label="Header value" placeholder="Value">').val(value || ''));
      row.append($('<button type="button" class="dt-icon-button" aria-label="Remove header">×</button>').on('click', function(){ row.remove(); }));
      $root.find('[name=headerRows]').append(row);
    };
    addHeader('Accept', 'application/json');
    addHeader('Content-Type', 'application/json');
    $root.on('click', '.dt-tab', function() {
      const name = this.dataset.tab;
      $root.find('.dt-tab').removeClass('is-active'); $(this).addClass('is-active');
      $root.find('.dt-tab-panel').removeClass('is-active'); $root.find('[data-panel="' + name + '"]').addClass('is-active');
    });
    $root.find('[name=addHeader]').on('click', function(){ addHeader('', ''); });
    $root.find('[name=formatJson]').on('click', function(){
      const input = $root.find('[name=body]');
      try { input.val(JSON.stringify(JSON.parse(input.val()), null, 2)); }
      catch (_) { DevTools.showMessage($root, 'The request body is not valid JSON.', true); }
    });
    $root.find('[name=clear]').on('click', function(){
      $root.find('[name=url],[name=body]').val(''); $root.find('[name=method]').val('GET');
      $root.find('[name=headerRows]').empty(); addHeader('Accept','application/json'); addHeader('Content-Type','application/json');
    });
    $root.find('[name=send]').on('click', function(){ DevTools.send($root); });
    $root.find('[name=url]').on('keydown', function(e){ if(e.key === 'Enter') DevTools.send($root); });
  },
  showMessage: function($root, message, isError) {
    $root.find('[name=response]').toggleClass('dt-response-empty', !isError).text(message);
  },
  send: async function($root) {
    const url = ($root.find('[name=url]').val() || '').trim();
    if (!url) { DevTools.showMessage($root, 'Enter a request URL first.', true); return; }
    const sendButton = $root.find('[name=send]');
    const previous = DevTools.controllers.get($root.get(0)); if (previous) previous.abort();
    const controller = new AbortController(); DevTools.controllers.set($root.get(0), controller);
    const headers = new Headers();
    let invalidHeader = '';
    $root.find('.dt-header-row').each(function(){
      const name = ($(this).find('.dt-header-name').val() || '').trim(); const value = ($(this).find('.dt-header-value').val() || '').trim();
      if (name) { try { headers.append(name, value); } catch (_) { invalidHeader = name; } }
    });
    if (invalidHeader) { DevTools.showMessage($root, 'Invalid header name: ' + invalidHeader, true); return; }
    const method = $root.find('[name=method]').val(); const body = $root.find('[name=body]').val();
    const options = { method: method, headers: headers, signal: controller.signal, credentials: 'same-origin' };
    if (!['GET','HEAD'].includes(method) && body) options.body = body;
    sendButton.prop('disabled', true).text('Sending…');
    $root.find('[name=status]').removeClass('ok error').text('Sending'); $root.find('[name=time],[name=size]').text('—');
    DevTools.showMessage($root, 'Waiting for response…', false); const started = performance.now();
    try {
      const response = await fetch(url, options); const text = await response.text(); const elapsed = Math.round(performance.now() - started);
      let display = text || '(empty response body)'; const contentType = response.headers.get('content-type') || '';
      if (contentType.includes('json') && text) { try { display = JSON.stringify(JSON.parse(text), null, 2); } catch (_) {} }
      $root.find('[name=response]').removeClass('dt-response-empty').text(display);
      $root.find('[name=status]').removeClass('ok error').addClass(response.ok ? 'ok' : 'error').text(response.status + ' ' + response.statusText);
      $root.find('[name=time]').text(elapsed + ' ms'); $root.find('[name=size]').text(new Blob([text]).size + ' B');
      const lines = []; response.headers.forEach(function(value, name){ lines.push(name + ': ' + value); });
      $root.find('[name=responseHeaders]').text(lines.join('\n') || 'No response headers returned.');
    } catch (error) {
      const elapsed = Math.round(performance.now() - started); const aborted = error && error.name === 'AbortError';
      $root.find('[name=status]').removeClass('ok').addClass('error').text(aborted ? 'Cancelled' : 'Request failed');
      $root.find('[name=time]').text(elapsed + ' ms');
      DevTools.showMessage($root, aborted ? 'The request was cancelled.' : 'The browser could not complete this request. Check the URL, network connection, TLS certificate, and the target API\'s CORS policy.\n\n' + (error.message || error), true);
    } finally { sendButton.prop('disabled', false).text('Send'); DevTools.controllers.delete($root.get(0)); }
  }
};
